"""Generate plain content definitions/resources from audited legacy registrations.
Run from repository root after tools/audit_content.py. Minecraft prototypes are
read from the already-resolved 26.3 client archive, never guessed from older APIs.
"""
from loot_schema import for_resource
from pathlib import Path
import json,re,zipfile,itertools,shutil,argparse
ROOT=Path(__file__).resolve().parents[1];legacy=ROOT/'src/main/resources/assets/thaumcraft';out=ROOT/'src/modern/resources';a=out/'assets/thaumcraft';d=out/'data/thaumcraft'
parser=argparse.ArgumentParser();parser.add_argument('--minecraft-client',type=Path,default=Path('/workspace/.gradle/caches/minecraftforge/forgegradle/mavenizer/caches/minecraft_tasks/26.3/client.jar'));args=parser.parse_args()
mc=zipfile.ZipFile(args.minecraft_client)
def save(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(for_resource(p,v),indent=2,ensure_ascii=False)+'\n')
def tc(n):return 'thaumcraft:'+n
audit=json.loads((ROOT/'docs/CONTENT-INVENTORY.json').read_text());config=(ROOT/'src/main/java/thaumcraft/common/config/ConfigBlocks.java').read_text().splitlines();blocks=[];fields={}
for row in audit:
 if row['kind']!='Blocks' or row['group']!='S':continue
 f=row['field'];cls=row['class'];line=next(l for l in config if 'BlocksTC.'+f+' =' in l)
 names=re.findall(r'"([\w]+)"',line)
 special={'fleshBlock':'flesh_block','shimmerleaf':'shimmerleaf','cinderpearl':'cinderpearl','vishroom':'vishroom','activatorRail':'activator_rail'}
 name=special.get(f,names[0] if names else None);assert name,f;fields[f]=name
 if name in ['metal_brass','metal_void','metal_thaumium']:continue
 kind={'BlockLogsTC':'log','BlockPlanksTC':'wood','BlockStairsTC':'stairs','BlockSlabTC':'slab','BlockPillar':'pillar','BlockFlesh':'flesh','BlockRailPowered':'rail','BlockMetalTC':'metal'}.get(cls,'plant' if cls.startswith('BlockPlant') else 'stone')
 base=''
 if kind=='stairs':base=fields[re.findall(r'BlocksTC\.(\w+)',line)[1]]
 if kind=='slab':base={'slabArcaneStone':'stone_arcane','slabArcaneBrick':'stone_arcane_brick','slabAncient':'stone_ancient','slabEldritch':'stone_eldritch_tile','slabGreatwood':'plank_greatwood','slabSilverwood':'plank_silverwood'}[f]
 blocks.append({'id':name,'kind':kind,'base':base,'legacy_field':f})
items=[];iconfig=(ROOT/'src/main/java/thaumcraft/common/config/ConfigItems.java').read_text()
existing={'amber','quicksilver','ingot_thaumium','ingot_void','ingot_brass','nugget_thaumium','nugget_void','nugget_brass','nugget_quicksilver'}
for args in re.findall(r'new ItemTCBase\(([^)]+)\)',iconfig):
 names=re.findall(r'"([\w]+)"',args);base,*variants=names
 for name in ([base+'_'+v for v in variants] if variants else [base]):
  if name not in existing:items.append(name)
# Legacy texture aliases are resolved below from the original item blockstates.
save(ROOT/'tools/simple_content.json',{'blocks':blocks,'materials':items,'tools':['thaumium_'+t for t in ['axe','sword','shovel','pick','hoe']],'armor':['thaumium_'+t for t in ['helm','chest','legs','boots']],'food':['chunk_'+m for m in ['beef','chicken','pork','fish','rabbit','mutton']]+['triple_meat_treat']})
j=['package thaumcraft.content;','','/** Generated by tools/generate_simple_content.py; behavior lives in SimpleContent. */','final class SimpleDefinitions {','    private SimpleDefinitions() {}','    static void register() {']
for b in blocks:j.append(f'        SimpleContent.block("{b["id"]}", "{b["kind"]}", "{b["base"]}");')
for name in items:j.append(f'        SimpleContent.material("{name}");')
j+=['    }','}'];(ROOT/'src/modern/java/thaumcraft/content/SimpleDefinitions.java').write_text('\n'.join(j)+'\n')
def itemdef(name,model):save(a/f'items/{name}.json',{'model':{'type':'minecraft:model','model':tc(model)}})
def model(name,o):save(a/f'models/block/{name}.json',o)
textures={}
for b in blocks:
 name=b['id'];kind=b['kind']
 if kind in ['stairs','slab']:continue
 if kind in ['stone','wood','log','metal','flesh']:
  old=json.loads((legacy/f'blockstates/{name}.json').read_text())['defaults']
  if 'textures' not in old:
   child=json.loads((legacy/('models/block/'+old['model'].split(':')[1]+'.json')).read_text());old={'model':child['parent'].replace('block/',''),'textures':child['textures']}
  m={'parent':'minecraft:block/'+old['model'],'textures':old['textures']};model(name,m);textures[name]=old['textures']
  variants={'':{'model':tc('block/'+name)}}
  if kind=='log':variants={'axis=x':{'model':tc('block/'+name),'x':90,'y':90},'axis=y':{'model':tc('block/'+name)},'axis=z':{'model':tc('block/'+name),'x':90}}
  save(a/f'blockstates/{name}.json',{'variants':variants})
 elif kind=='plant':
  model(name,{'parent':'minecraft:block/cross','render_type':'minecraft:cutout','textures':{'cross':tc('blocks/'+name)}});save(a/f'blockstates/{name}.json',{'variants':{'':{'model':tc('block/'+name)}}})
 elif kind=='pillar':
  # Preserve the original OBJ triangles and UVs. Forge 66.0.13's OBJ baker
  # starts its quad cursor at 0 then increments before writing, overflowing it.
  vertices=[];uvs=[];triangles=[]
  for line in (legacy/'models/block/pillar.obj').read_text().splitlines():
   parts=line.split()
   if not parts:continue
   if parts[0]=='v':vertices.append(list(map(float,parts[1:4])))
   elif parts[0]=='vt':uvs.append([float(parts[1]),float(parts[2])])
   elif parts[0]=='f':
    assert len(parts)==4,'Expected original triangular pillar mesh'
    face=[]
    for ref in parts[1:]:
     v,uv,*_=map(int,ref.split('/'));face.append(vertices[v-1]+uvs[uv-1])
    triangles.append(face)
  texture={'pillar_arcane':'pillar_normal','pillar_ancient':'pillar_ancient','pillar_eldritch':'pillar_eldritch'}[name]
  model(name,{'parent':'minecraft:block/block','loader':'thaumcraft:triangles','textures':{'texture':tc('blocks/'+texture),'particle':tc('blocks/'+texture)},'triangles':triangles,'display':{'gui':{'rotation':[30,225,0],'translation':[0,-4,0],'scale':[0.3,0.3,0.3]}}})
  save(a/f'blockstates/{name}.json',{'variants':{'facing='+f:{'model':tc('block/'+name),'y':rot} for f,rot in [('north',0),('east',90),('south',180),('west',270)]}})
 elif kind=='rail':
  # The original registers BlockRailPowered, despite its activator_rail ID.
  proto='powered_rail';template=json.loads(mc.read(f'assets/minecraft/blockstates/{proto}.json'))
  for v in template['variants'].values():v['model']=v['model'].replace('minecraft:block/'+proto,tc('block/'+name))
  save(a/f'blockstates/{name}.json',template)
  refs={v['model'].split(':',1)[1] for v in template['variants'].values()}
  for ref in refs:
   suffix=ref[len('block/'+name):];o=json.loads(mc.read('assets/minecraft/models/block/'+proto+suffix+'.json'));o['textures']={'rail':tc('blocks/rail_activator'+('_powered' if '_on' in suffix else ''))};save(a/f'models/{ref}.json',o)
  save(a/f'models/item/{name}.json',{'parent':'minecraft:item/generated','textures':{'layer0':tc('blocks/rail_activator')}})
 itemdef(name,('item/' if kind=='rail' else 'block/')+name)
for b in blocks:
 name=b['id'];kind=b['kind'];base=b['base']
 if kind not in ['stairs','slab']:continue
 tex=textures[base];alltex=tex.get('all',tex.get('side',tex.get('particle')));ts={'bottom':tex.get('down',alltex),'top':tex.get('up',alltex),'side':tex.get('north',alltex)}
 proto='oak_stairs' if kind=='stairs' else 'oak_slab';o=json.loads(mc.read(f'assets/minecraft/blockstates/{proto}.json'))
 for v in o['variants'].values():
  v['model']=tc('block/'+base) if kind=='slab' and v['model']=='minecraft:block/oak_planks' else v['model'].replace('minecraft:block/'+proto,tc('block/'+name))
 save(a/f'blockstates/{name}.json',o)
 for suffix,parent in ([('', 'stairs'),('_inner','inner_stairs'),('_outer','outer_stairs')] if kind=='stairs' else [('', 'slab'),('_top','slab_top')]):model(name+suffix,{'parent':'minecraft:block/'+parent,'textures':ts})
 itemdef(name,'block/'+name)
# Loot includes exact double-slab counts and the legacy pillar's two base blocks.
for b in blocks:
 name=b['id'];kind=b['kind']
 if name in ['stone_ancient_rock','stone_ancient_doorway']:continue
 entry={'type':'minecraft:item','name':tc(name)}
 if kind=='slab':entry['modifier']=[{'type':'minecraft:set_count','count':2,'condition':{'type':'minecraft:match_block','blocks':tc(name),'state':{'type':'double'}}}]
 if kind=='pillar':entry['name']=tc({'pillar_arcane':'stone_arcane','pillar_ancient':'stone_ancient','pillar_eldritch':'stone_eldritch_tile'}[name]);entry['modifier']=[{'type':'minecraft:set_count','count':2}]
 save(d/f'loot_table/blocks/{name}.json',{'type':'minecraft:block','pools':[{'rolls':1,'condition':{'type':'minecraft:survives_explosion'},'entries':[entry]}]})
for name in items+['thaumium_'+n for n in ['axe','sword','shovel','pick','hoe','helm','chest','legs','boots']]+['chunk_'+n for n in ['beef','chicken','pork','fish','rabbit','mutton']]+['triple_meat_treat']:
 if (legacy/f'models/item/{name}.json').exists():o=json.loads((legacy/f'models/item/{name}.json').read_text());o['parent']=o['parent'].replace('item/','minecraft:item/') if ':' not in o['parent'] else o['parent']
 else:
  prefix,_,variant=name.partition('_');blockstate=legacy/f'blockstates/{prefix}.json'
  texture=tc('items/'+name)
  if blockstate.exists() and variant:
   entry=json.loads(blockstate.read_text()).get('variants',{}).get(variant,{})
   texture=entry.get('textures',{}).get('layer0',texture)
  o={'parent':'minecraft:item/generated','textures':{'layer0':texture}}
 assert (legacy/'textures'/(o['textures']['layer0'].split(':')[1]+'.png')).exists(),name
 save(a/f'models/item/{name}.json',o);itemdef(name,'item/'+name)
# Armor textures are copied, never recolored or resampled.
for layer,original in [('humanoid','thaumium_1'),('humanoid_leggings','thaumium_2')]:
 p=a/f'textures/entity/equipment/{layer}/thaumium.png';p.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(legacy/f'textures/entity/armor/{original}.png',p)
save(a/'equipment/thaumium.json',{'layers':{'humanoid':[{'texture':tc('thaumium')}],'humanoid_leggings':[{'texture':tc('thaumium')}]}})
# Preserve every existing language entry, then append exact legacy translations.
langs={}
for language in ['en_us','es_es']:
 old={}
 for line in ((legacy/f'lang/{language}.lang').read_text() if (legacy/f'lang/{language}.lang').exists() else '').splitlines():
  if '=' in line and not line.startswith('#'):key,value=line.split('=',1);old[key]=value
 p=a/f'lang/{language}.json';o=json.loads(p.read_text())
 for b in blocks:o['block.thaumcraft.'+b['id']]=old.get('tile.'+b['id']+'.name',b['id'].replace('_',' ').title())
 for name in items+['thaumium_'+n for n in ['axe','sword','shovel','pick','hoe','helm','chest','legs','boots']]+['chunk_'+n for n in ['beef','chicken','pork','fish','rabbit','mutton']]+['triple_meat_treat']:
  key='item.'+name+'.name'
  for prefix in ['nugget','cluster','plate','mind','module','chunk']:
   if name.startswith(prefix+'_'):key='item.'+prefix+'.'+name[len(prefix)+1:]+'.name'
  o['item.thaumcraft.'+name]=old.get(key,name.replace('_',' ').title())
 if language=='es_es':o.update(json.loads((ROOT/'tools/es_simple_content.json').read_text()))
 save(p,o)
# Tags extend earlier content rather than replacing it.
def tag(namespace,kind,name,values):
 p=out/f'data/{namespace}/tags/{kind}/{name}.json';o=json.loads(p.read_text()) if p.exists() else {'replace':False,'values':[]};o['values']=list(dict.fromkeys(o['values']+values));save(p,o)
wood=[b['id'] for b in blocks if b['kind'] in ['wood','log'] or b['base'].startswith('plank_')]
stone=[b['id'] for b in blocks if b['kind'] in ['stone','metal','pillar'] or (b['kind'] in ['slab','stairs'] and b['id'] not in wood)]
tag('minecraft','block','mineable/axe',[tc(n) for n in wood]);tag('minecraft','block','mineable/pickaxe',[tc(n) for n in stone+['activator_rail']]);tag('minecraft','block','beacon_base_blocks',[tc(b['id']) for b in blocks if b['kind'] in ['stone','metal']])
for kind in ['block','item']:
 for tagname,names in [('logs',['log_greatwood','log_silverwood']),('logs_that_burn',['log_greatwood','log_silverwood']),('planks',['plank_greatwood','plank_silverwood']),('wooden_slabs',['slab_greatwood','slab_silverwood']),('wooden_stairs',['stairs_greatwood','stairs_silverwood']),('rails',['activator_rail'])]:tag('minecraft',kind,tagname,[tc(n) for n in names])
tag('thaumcraft','item','repairs_thaumium',[tc('ingot_thaumium')])
tag('minecraft','item','wolf_food',[tc('triple_meat_treat')])
for name in items:
 prefix,_,variant=name.partition('_')
 if prefix in ['nugget','cluster','plate']:tag('c','item',{'nugget':'nuggets','cluster':'clusters','plate':'plates'}[prefix]+'/'+variant,[tc(name)])
# Ordinary conversions only: arcane/research-gated recipes are not bypassed.
def recipe(name,obj,material):
 save(d/f'recipe/{name}.json',obj);save(d/f'advancement/recipes/{name}.json',{'parent':'minecraft:recipes/root','criteria':{'material':{'trigger':'minecraft:inventory_changed','conditions':{'items':[{'items':material}]}},'recipe':{'trigger':'minecraft:recipe_unlocked','conditions':{'recipes':tc(name)}}},'requirements':[['material','recipe']],'rewards':{'recipes':[tc(name)]}})
def shaped(name,pattern,key,result,count=1):recipe(name,{'type':'minecraft:crafting_shaped','category':'building','pattern':pattern,'key':key,'result':{'id':tc(result),'count':count}},next(iter(key.values())))
for b in blocks:
 if b['kind']=='stairs':shaped(b['id'],['#  ','## ','###'],{'#':tc(b['base'])},b['id'],4)
 if b['kind']=='slab':shaped(b['id'],['###'],{'#':tc(b['base'])},b['id'],6)
for wood in ['greatwood','silverwood']:recipe('planks_'+wood,{'type':'minecraft:crafting_shapeless','category':'building','ingredients':[tc('log_'+wood)],'result':{'id':tc('plank_'+wood),'count':4}},tc('log_'+wood))
shaped('flesh_block',['###']*3,{'#':'minecraft:rotten_flesh'},'flesh_block');recipe('flesh_from_block',{'type':'minecraft:crafting_shapeless','category':'misc','ingredients':[tc('flesh_block')],'result':{'id':'minecraft:rotten_flesh','count':9}},tc('flesh_block'))
for i,combo in enumerate(itertools.combinations(['beef','chicken','pork','fish','rabbit','mutton'],3)):
 ingredients=[tc('chunk_'+s) for s in combo]+['minecraft:sugar'];recipe('triple_meat_treat_'+str(i),{'type':'minecraft:crafting_shapeless','category':'misc','group':'thaumcraft:triple_meat_treat','ingredients':ingredients,'result':{'id':tc('triple_meat_treat')}},ingredients[0])
for source,target,count in [('shimmerleaf','thaumcraft:quicksilver',1),('cinderpearl','minecraft:blaze_powder',1),('cluster_iron','minecraft:iron_ingot',2),('cluster_gold','minecraft:gold_ingot',2),('cluster_copper','minecraft:copper_ingot',2),('cluster_cinnabar','thaumcraft:quicksilver',2),('cluster_quartz','minecraft:quartz',2)]:
 obj={'type':'minecraft:smelting','category':'misc','ingredient':tc(source),'result':{'id':target,'count':count},'experience':1.0,'cookingtime':200}
 if source in ['shimmerleaf','cinderpearl']:obj={'type':'minecraft:crafting_shapeless','category':'misc','ingredients':[tc(source)],'result':{'id':target,'count':count}}
 recipe(source+'_conversion',obj,tc(source))
for tool,pattern in {'sword':['I','I','S'],'pick':['III',' S ',' S '],'axe':['II','SI','S '],'shovel':['I','S','S'],'hoe':['II','S ','S '],'helm':['III','I I'],'chest':['I I','III','III'],'legs':['III','I I','I I'],'boots':['I I','I I']}.items():
 key={'I':'thaumcraft:ingot_thaumium'}
 if any('S' in row for row in pattern):key['S']='minecraft:stick'
 shaped('thaumium_'+tool,pattern,key,'thaumium_'+tool)
for metal in ['iron','brass','thaumium','void']:
 shaped('plate_'+metal,['###'],{'#':'minecraft:iron_ingot' if metal=='iron' else tc('ingot_'+metal)},'plate_'+metal,3)
recipe('convert_iron_nugget',{'type':'minecraft:crafting_shapeless','category':'misc','ingredients':[tc('nugget_iron')],'result':{'id':'minecraft:iron_nugget'}},tc('nugget_iron'))
for metal in ['copper','quartz']:
 target='minecraft:copper_ingot' if metal=='copper' else 'minecraft:quartz'
 recipe(metal+'_from_nuggets',{'type':'minecraft:crafting_shaped','category':'misc','pattern':['###']*3,'key':{'#':tc('nugget_'+metal)},'result':{'id':target}},tc('nugget_'+metal))
recipe('quartz_to_nuggets',{'type':'minecraft:crafting_shapeless','category':'misc','ingredients':['minecraft:quartz'],'result':{'id':tc('nugget_quartz'),'count':9}},'minecraft:quartz')
# Legacy sounds: only the one actually registered/used by this content batch.
sounds=json.loads((legacy/'sounds.json').read_text());save(a/'sounds.json',{'gore':sounds['gore']})
for sound in ['gore1.ogg','gore2.ogg']:
 p=a/'sounds'/sound;p.parent.mkdir(exist_ok=True);shutil.copyfile(legacy/'sounds'/sound,p)
print(len(blocks),'new blocks;',len(items),'plain material variants; 9 tools/armor and 7 foods; resources generated.')

lines=['# Contenido sin una mecánica nueva', '', 'Lote portado sobre los ocho bloques y nueve materiales del paso 3. Los IDs usan el prefijo `thaumcraft:`. Estas piezas funcionan con estados y componentes de Minecraft; sus usos en sistemas pendientes se activarán con esos sistemas.', '', '## Bloques añadidos (35)', '', '| ID | Comportamiento |', '|---|---|']
labels={'stone':'piedra','wood':'tablones','log':'tronco orientable','stairs':'escalera','slab':'losa simple/doble','plant':'planta con suelo y efectos','metal':'bloque de metal','flesh':'bloque de carne','pillar':'pilar orientable, colisión de dos bloques','rail':'raíl propulsor (clase original BlockRailPowered)'}
for block in blocks:lines.append(' | '.join(['| `'+block['id']+'`',labels[block['kind']]+' |']))
for title,names in [('Materiales añadidos (35)',items),('Herramientas de taumio (5)',['thaumium_'+t for t in ['axe','sword','shovel','pick','hoe']]),('Armadura de taumio (4)',['thaumium_'+t for t in ['helm','chest','legs','boots']]),('Alimentos (7)',['chunk_'+m for m in ['beef','chicken','pork','fish','rabbit','mutton']]+['triple_meat_treat'])]:
 lines+=['','## '+title,'']+['- `'+name+'`' for name in names]
lines+=['', '## Usos que siguen dependiendo de otro sistema', '', 'Las mejoras de matriz, constructos alquímicos, mecanismos, módulos, resonadores, semillas y demás ingredientes están registrados como materiales o bloques base. Esto no implementa infusión, alquimia, gólems ni los objetos que los utilizan. Sus recetas especiales no se sustituyen por recetas gratuitas. Los troncos y tablones están disponibles; el crecimiento y la generación de los árboles se incluyen en M01.', '', 'La primera mecánica implementada aparte añade las velas y nitores en 16 colores (M02). El detalle de los sistemas y su estado está en [MECHANICS-ROADMAP.md](MECHANICS-ROADMAP.md).', '']
(ROOT/'docs/SIMPLE-CONTENT.md').write_text('\n'.join(lines))
